export default function prepare({ videoId, videos, captions }) {
  const video = videos.find((v) => v.id === videoId),
    track = captions.find((c) => c.id && c.snippet?.videoId === videoId);
  if (!video?.snippet?.title || !video.snippet.categoryId || !track)
    throw Error("Video or caption track missing or mismatched");
  return { captionId: track.id, snippet: video.snippet };
}

