export default async function prepare({ videoId, snippet, chapters, resolution }, ctx) {
  const text = chapters.description?.trim();
  if (!text || !/^00:00\s/m.test(text))
    throw Error("Review chapter timestamps: first must start at 00:00");
  const key = "youtube-chapters:" + videoId,
    old = await ctx.state.get(key);
  if (old?.status === "pending" && resolution === "applied") {
    await ctx.state.set(key, { status: "confirmed" });
    return { write: false, endpoint: "/videos?part=snippet", body: {}, key, videoId };
  }
  if (old?.status === "pending" && resolution !== "absent")
    throw Error("Update result unknown; inspect video and choose applied or absent");
  const next = {
    title: snippet.title,
    categoryId: snippet.categoryId,
    description: (snippet.description ? snippet.description + "\n\n" : "") + "Chapters\n" + text,
  };
  for (const k of ["tags", "defaultLanguage", "defaultAudioLanguage"])
    if (snippet[k] !== undefined) next[k] = snippet[k];
  if (new TextEncoder().encode(next.description).length > 5000)
    throw Error("Description exceeds YouTube limit");
  await ctx.state.set(key, { status: "pending" });
  return {
    endpoint: "/videos?part=snippet",
    body: { id: videoId, snippet: next },
    key,
    write: true,
    videoId,
  };
}

